<script>
// Update bookmark count from localStorage
function updateBookmarkCount() {
  const bookmarkBadge = document.getElementById('bookmarkCount');
  if (!bookmarkBadge) return;

  try {
    const bookmarks = JSON.parse(localStorage.getItem('bookmark')) || [];
    const count = bookmarks.length;
    bookmarkBadge.textContent = count;
    // Hide badge if count is 0
    bookmarkBadge.style.display = count > 0 ? 'flex' : 'none';
  } catch (e) {
    console.log(`Exception updating bookmark count: ${e}`);
    bookmarkBadge.style.display = 'none';
  }
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', updateBookmarkCount);

// Listen for storage changes from other tabs
globalThis.addEventListener('storage', updateBookmarkCount);
</script>
